/**
 * The typed API client. Every request and response type comes from the backend's OpenAPI
 * schema (schema.d.ts, generated by `make api-types`); nothing here declares its own shapes.
 */
import createClient, { type Middleware } from "openapi-fetch";

import type { components, paths } from "./schema";

export type Schemas = components["schemas"];

export const API_BASE = process.env.NEXT_PUBLIC_LANE_API_URL ?? "http://localhost:8000";

let token: string | null = null;

export function hasToken(): boolean {
  return token !== null;
}

/** Use a demo sign-in token for every request (null signs out). */
export function setToken(next: string | null): void {
  token = next;
}

// Asked without anyone signed in: answered here, never sent. Only signing in and the health
// check go out, so the app under the sign-in page fetches nothing.
const OPEN = /^\/api\/v1\/(auth\/|health$)/;

const auth: Middleware = {
  onRequest({ request }) {
    if (token) {
      request.headers.set("Authorization", `Bearer ${token}`);
      return request;
    }
    if (OPEN.test(new URL(request.url).pathname)) return request;
    return new Response(JSON.stringify({ detail: "Sign in to see this" }), {
      status: 401,
      headers: { "content-type": "application/json" },
    });
  },
};

export const api = createClient<paths>({ baseUrl: API_BASE, cache: "no-store" });
api.use(auth);

/** A URL for what cannot send headers (images, event streams), carrying the token if any. */
export function authedUrl(path: string): string {
  const url = new URL(path, API_BASE);
  if (token) url.searchParams.set("access_token", token);
  return url.toString();
}

/** The API's error message, or a fallback. */
export function errorMessage(error: unknown, fallback: string): string {
  if (error && typeof error === "object" && "detail" in error) {
    const detail = (error as { detail: unknown }).detail;
    if (typeof detail === "string") return detail;
  }
  return fallback;
}

export type Health = Schemas["Health"];
export type SubmissionSummary = Schemas["SubmissionSummary"];
export type IngestResult = Schemas["IngestResponse"];

export async function getHealth(signal?: AbortSignal): Promise<Health> {
  const { data, error, response } = await api.GET("/api/v1/health", { signal });
  if (!data) throw new Error(errorMessage(error, `Health check failed with ${response.status}`));
  return data;
}

export async function listSubmissions(signal?: AbortSignal): Promise<SubmissionSummary[]> {
  const { data, error, response } = await api.GET("/api/v1/submissions", { signal });
  if (!data)
    throw new Error(errorMessage(error, `Could not load submissions (${response.status})`));
  return data;
}

export async function uploadEmail(file: File): Promise<IngestResult> {
  const { data, error, response } = await api.POST("/api/v1/intake/eml", {
    body: file as unknown as string,
    bodySerializer: (body) => body as unknown as BodyInit,
    headers: { "Content-Type": "message/rfc822" },
  });
  if (!data) throw new Error(errorMessage(error, `Upload failed (${response.status})`));
  return data;
}
